class Droid:
    def __init__(self, name, battery_level):
        self.name = name
        self.battery_level = battery_level

    def greet(self):
        print(f"Greetings. I am {self.name}, Worker Unit.")

class CommanderDroid(Droid):
    def __init__(self, name, battery_level, rank):
        # Call parent's __init__ to set name and battery
        super().__init__(name, battery_level)
        # Add new attribute
        self.rank = rank

    def greet(self):
        print(f"Commander {self.name}, Rank {self.rank}, reporting.")

# Create a ranked commander
cmd = CommanderDroid('APEX-1', 100, 'General')
cmd.greet()
print(f"Battery: {cmd.battery_level}%")  # Inherited attribute works!

